D=json.loads((OUT/'design-data.json').read_text())
def draw(r,w):
    x=r.random();s=0
    for i,p in enumerate(w):
        s+=p
        if x<s:return i
    return len(w)-1
def sim(minutes,samples=16000):
    mobs=minutes//3;gathers=min(50,minutes*16//60);bosses=min(3,minutes//60);trips=math.ceil(minutes/20)
    r=random.Random(20261028+minutes);nets=[];loss=0;reds=0;gross=0
    for _ in range(samples):
        bags=[[] for _ in range(trips)];red=False
        for i in range(mobs):
            tier=draw(r,D['mobMix'])
            if r.random()<D['mobTriggers'][tier]:
                q=draw(r,D['qualityProb']);bags[min(trips-1,int((i+.5)*minutes/mobs/20))].append(D['values'][q]);red|=q==5
        for i in range(gathers):
            tier=draw(r,D['tierMix'])
            if r.random()<D['gatherTrigger'][tier]:
                q=draw(r,D['qualityProb']);bags[min(trips-1,int((i+.5)*minutes/gathers/20))].append(D['values'][q]);red|=q==5
        for i in range(bosses):bags[min(trips-1,(i+1)*3-1)].extend([30,30])
        net=0
        for bag in bags:
            bag.sort(reverse=True);gross+=sum(bag);pool=bag[3:];lost=0
            if pool and r.random()<.3:lost=sum(r.sample(pool,min(len(bag)//2,len(pool))))
            loss+=lost;net+=sum(bag)-lost
        nets.append(net);reds+=red
    nets.sort();gp=sum(x*y for x,y in zip(D['tierMix'],D['gatherTrigger']));mp=sum(x*y for x,y in zip(D['mobMix'],D['mobTriggers']))
    expected=(mobs*mp+gathers*gp)*19.5+bosses*60
    return dict(minutes=minutes,mobs=mobs,gathers=gathers,bosses=bosses,trips=trips,samples=samples,gross=expected,sampleGross=gross/samples,rawSampleMean=statistics.mean(nets),mean=expected-loss/samples,p10=nets[int(samples*.1)],p50=nets[int(samples*.5)],p90=nets[int(samples*.9)],meanLoss=loss/samples,redProbability=reds/samples)
D['simulations']=[sim(m) for m in [30,60,120,180]]
